document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".arrow-collapse").forEach(function(s){s.addEventListener("click",function(s){s.preventDefault(),s.stopPropagation();var e=this.getAttribute("data-target"),t=document.querySelector(e);if(t&&!t.classList.contains("collapsing"))if(t.classList.contains("show")){var l=t.getBoundingClientRect().height;t.style.height=l+"px",t.offsetHeight,t.classList.remove("collapse","show"),t.classList.add("collapsing"),t.style.height="0px",this.classList.add("collapsed"),setTimeout(()=>{t.classList.remove("collapsing"),t.classList.add("collapse"),t.style.height=""},1e3)}else t.classList.remove("collapse"),t.classList.add("collapsing"),l=t.scrollHeight,t.style.height="0px",t.offsetHeight,t.style.height=l+"px",this.classList.remove("collapsed"),setTimeout(()=>{t.classList.remove("collapsing"),t.classList.add("collapse","show"),t.style.height=""},1e3)})})});